import numpy as np

def kernel(dst, src):
    inv = 255 - src[:, :, 3:4]
    return np.clip(src + (dst * inv) // 255, 0, 255).astype(np.uint8)

import numpy as np

def kernel(linear):
    s = 1.055 * np.power(linear, 1.0 / 2.4) - 0.055
    return np.clip(np.rint(s * 255.0), 0, 255).astype(np.uint8)
